import{_ as a,o as e,c as n,S as p}from"./chunks/framework.D1Ss-Xl7.js";const u=JSON.parse('{"title":"Github团队协作","description":"社畜也快半年了，说实话工作确实没有学生生活有趣。每天基本都是坐在电脑前写代码，可能我是那种更喜欢新鲜生活的人吧。对于重复的生活很容易就厌倦了，但生活由不得自己，上班的理由很简单，仅仅是因为穷。学生时代写代码基本都是一个人单干，但进入公司就开…","frontmatter":{"title":"Github团队协作","date":"2017-09-16 22:30","comments":true,"archives":2017,"tags":["github"]},"headers":[],"relativePath":"posts/2017-09-16-github-workflow/index.md","filePath":"posts/2017/2017-09-17-Github-workflow.md"}'),l={name:"posts/2017-09-16-github-workflow/index.md"};function o(t,s,r,c,i,d){return e(),n("div",null,[...s[0]||(s[0]=[p(`<p>社畜也快半年了，说实话工作确实没有学生生活有趣。每天基本都是坐在电脑前写代码，可能我是那种更喜欢新鲜生活的人吧。对于重复的生活很容易就厌倦了，但生活由不得自己，上班的理由很简单，仅仅是因为穷。学生时代写代码基本都是一个人单干，但进入公司就开始正式的团队协作，也算是学到很多团队合作的知识了吧。特别是利用 Github 进行高效的合作开发。</p><h2 id="github-协作开发" tabindex="-1">Github 协作开发 <a class="header-anchor" href="#github-协作开发" aria-label="Permalink to &quot;Github 协作开发&quot;">​</a></h2><p>首先是切换到需要开发的分支，这里我们假设要在<code>dev</code>分支上进行开发。</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">git</span><span style="color:#032F62;"> checkout</span><span style="color:#032F62;"> dev</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>然后，在 dev 分支上建立属于自己的分支。命名可以以功能命名也可以用解决的 issue 命名。例如：<code>dev-add-page dev-issue20</code>，之后再切换到自己建立的分支。</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">git</span><span style="color:#032F62;"> branch</span><span style="color:#032F62;"> dev-issue20</span></span>
<span class="line"><span style="color:#6F42C1;">git</span><span style="color:#032F62;"> checkout</span><span style="color:#032F62;"> dev-issue20</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>这样，就可以在自己分支上开发了，开发之后 push 到服务器上，再请求<code>pull request</code>进行合并操作，在<code>pull request</code>的时候，可以让同事来进行代码 review 保证开发质量。</p><p>协作要用到的 Github 命令很简单，之后再说说经常用的其他命令。例如，当我们写了半天发现自己在错误的分支上进行了开发，该怎么处理呢？我们可以使用<code>git stash</code>命令来把临时修改隐藏起来。</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">git</span><span style="color:#032F62;"> stash</span></span>
<span class="line"><span style="color:#6F42C1;">git</span><span style="color:#032F62;"> checkout</span><span style="color:#032F62;"> dev-issue20</span></span>
<span class="line"><span style="color:#6F42C1;">git</span><span style="color:#032F62;"> stash</span><span style="color:#032F62;"> pop</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>如果我们不小心在 dev 分支上直接进行了开发，可以使用上面的命令迅速把自己的修改切换到自己的分支上。</p><p>还有一种情况是，我们在自己的分支上进行开发的过程中，<code>dev</code>分支上合并了其他同事的代码，我们需要和<code>dev</code>分支保持一致。这时可以使用<code>git pull origin dev</code>分支来同步其他同事的代码，避免自己的代码和主分支产生冲突。</p><p>自己的分支在上传到服务器并合并之后通常服务器会删掉这个分支，但本地还是会保留。我们需要定期删掉自己本地已经合并的分支，这里推荐使用下面的命令。</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">git</span><span style="color:#032F62;"> branch</span><span style="color:#005CC5;"> --merged</span><span style="color:#D73A49;"> |</span><span style="color:#6F42C1;"> egrep</span><span style="color:#005CC5;"> -v</span><span style="color:#032F62;"> &quot;(^\\*|master|dev)&quot;</span><span style="color:#D73A49;"> |</span><span style="color:#6F42C1;"> xargs</span><span style="color:#032F62;"> git</span><span style="color:#032F62;"> branch</span><span style="color:#005CC5;"> -d</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>正则表达式里面是不需要删除的分支。</p><p>有时候发现某个分支做的功能被砍掉了，然后需要删掉这个分支。可以使用下面的命令：</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">git</span><span style="color:#032F62;"> push</span><span style="color:#005CC5;"> -d</span><span style="color:#032F62;"> origin</span><span style="color:#D73A49;"> &lt;</span><span style="color:#032F62;">branch_nam</span><span style="color:#24292E;">e</span><span style="color:#D73A49;">&gt;</span></span>
<span class="line"><span style="color:#6F42C1;">git</span><span style="color:#032F62;"> branch</span><span style="color:#005CC5;"> -d</span><span style="color:#D73A49;"> &lt;</span><span style="color:#032F62;">branch_nam</span><span style="color:#24292E;">e</span><span style="color:#D73A49;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>分别删掉远程服务器和本地的分支。</p><p>有时候发现自己写的思路是错的，需要舍弃现在所有的修改，可以使用<code>reset</code>命令来重置。</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">git</span><span style="color:#032F62;"> reset</span><span style="color:#005CC5;"> --hard</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>当然这个操作比较危险，你应该慎用。</p><p>当你需要移除所有新加的文件，但这些文件还没加入库当中。你可以使用<code>clean</code>命令来清除所有新加文件。</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">git</span><span style="color:#032F62;"> clean</span><span style="color:#005CC5;"> -f</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>目前经常使用的就是这么多，如果大家有更好的学习<code>Git</code>命令的推荐资料，欢迎留言。谢谢！</p><p>参考：</p><p><a href="https://stackoverflow.com/questions/6127328/how-can-i-delete-all-git-branches-which-have-been-merged" target="_blank" rel="noreferrer">Stack Overflow</a></p><p><a href="https://github.com/geeeeeeeeek/git-recipes" target="_blank" rel="noreferrer">高质量的 Git 中文教程</a></p><p><a href="https://git-scm.com/book/en/v2" target="_blank" rel="noreferrer">Pro Git</a></p>`,27)])])}const h=a(l,[["render",o]]);export{u as __pageData,h as default};
